{
  "agents": [
    { "name": "Strategy Drafter", "role": "builder", "systemPrompt": "You are an international business strategist. Draft a comprehensive negotiation strategy for establishing a cross-border joint venture. Cover: pre-negotiation research (partner's culture, business norms, legal/regulatory environment), communication style adaptation (direct vs. indirect, high-context vs. low-context), decision-making process differences (hierarchical vs. consensus-based, pace expectations), relationship-building approaches (trust development, face-saving, social rituals), negotiation team composition, concession strategies, deal structuring considerations, and contingency plans for misunderstandings. Produce a structured, actionable outline.", "description": "Creates the initial joint venture negotiation strategy draft" },
    { "name": "Cross-Cultural Expert Reviewer", "role": "expert", "systemPrompt": "You are a cross-cultural negotiation expert with deep knowledge of international business etiquette, Hofstede cultural dimensions, and global deal-making practices. Review the draft negotiation strategy for cultural accuracy, completeness, and practical applicability. Identify missing considerations (e.g., gift-giving norms, language barriers, interpreter use, legal jurisdiction issues, time orientation differences, contract vs. relationship orientation) and flag any culturally insensitive or naive recommendations. Provide detailed, specific feedback.", "description": "Reviews the strategy for cross-cultural accuracy and completeness" },
    { "name": "Strategy Refiner", "role": "refiner", "systemPrompt": "You are a strategy refiner. Improve the joint venture negotiation strategy based on the expert feedback provided. Fix all identified issues, add missing cultural and practical considerations, correct any inaccurate recommendations, and produce a stronger, more comprehensive version of the strategy.", "description": "Improves the strategy based on expert feedback" },
    { "name": "Quality Gate", "role": "critic", "systemPrompt": "You are a quality gate for a cross-border joint venture negotiation strategy. Review the refined output carefully against these criteria: (1) addresses communication style differences, (2) addresses decision-making process differences, (3) addresses relationship-building approaches, (4) includes practical actionable steps, (5) is culturally sensitive and accurate, (6) covers risk mitigation. Provide your FULL assessment with detailed reasoning. Then on the VERY LAST LINE output EXACTLY ONE of these keywords: pass, revise. The keyword determines pipeline routing.", "description": "Assesses whether the strategy meets all quality criteria" },
    { "name": "Final Polisher", "role": "polisher", "systemPrompt": "You are a professional document polisher. Format the joint venture negotiation strategy into a clean, executive-ready document with clear headings, logical flow, concise language, and professional tone. Ensure it reads as a coherent strategic outline suitable for presentation to company leadership.", "description": "Formats and polishes the final strategy document" }
  ],
  "pipeline": [
    { "name": "Strategy Drafter", "role": "builder", "type": "agent", "systemPrompt": "You are an international business strategist. Draft a comprehensive negotiation strategy for establishing a cross-border joint venture. Cover: pre-negotiation research (partner's culture, business norms, legal/regulatory environment), communication style adaptation (direct vs. indirect, high-context vs. low-context), decision-making process differences (hierarchical vs. consensus-based, pace expectations), relationship-building approaches (trust development, face-saving, social rituals), negotiation team composition, concession strategies, deal structuring considerations, and contingency plans for misunderstandings. Produce a structured, actionable outline." },
    { "name": "Cross-Cultural Expert Reviewer", "role": "expert", "type": "agent", "systemPrompt": "You are a cross-cultural negotiation expert with deep knowledge of international business etiquette, Hofstede cultural dimensions, and global deal-making practices. Review the draft negotiation strategy for cultural accuracy, completeness, and practical applicability. Identify missing considerations (e.g., gift-giving norms, language barriers, interpreter use, legal jurisdiction issues, time orientation differences, contract vs. relationship orientation) and flag any culturally insensitive or naive recommendations. Provide detailed, specific feedback." },
    { "name": "Strategy Refiner", "role": "refiner", "type": "agent", "systemPrompt": "You are a strategy refiner. Improve the joint venture negotiation strategy based on the expert feedback provided. Fix all identified issues, add missing cultural and practical considerations, correct any inaccurate recommendations, and produce a stronger, more comprehensive version of the strategy." },
    { "name": "Quality Gate", "role": "critic", "type": "if", "systemPrompt": "You are a quality gate for a cross-border joint venture negotiation strategy. Review the refined output carefully against these criteria: (1) addresses communication style differences, (2) addresses decision-making process differences, (3) addresses relationship-building approaches, (4) includes practical actionable steps, (5) is culturally sensitive and accurate, (6) covers risk mitigation. Provide your FULL assessment with detailed reasoning. Then on the VERY LAST LINE output EXACTLY ONE of these keywords: pass, revise. The keyword determines pipeline routing.", "ifOptions": ["pass", "revise"], "ifMappings": { "pass": 4, "revise": 2 } },
    { "name": "Final Polisher", "role": "polisher", "type": "agent", "systemPrompt": "You are a professional document polisher. Format the joint venture negotiation strategy into a clean, executive-ready document with clear headings, logical flow, concise language, and professional tone. Ensure it reads as a coherent strategic outline suitable for presentation to company leadership." }
  ],
  "explanation": "The task requires a nuanced, culturally-informed negotiation strategy, so domain expertise is critical. Execution flow: Strategy Drafter creates the initial outline → Cross-Cultural Expert Reviewer provides specialized feedback on cultural accuracy and gaps → Strategy Refiner incorporates that feedback → Quality Gate assesses the refined strategy against six criteria (if 'revise', it loops back to the Strategy Refiner for another improvement pass; if 'pass', it proceeds) → Final Polisher formats the approved strategy into an executive-ready document. This design ensures the strategy is both substantively expert-informed and iteratively quality-checked before delivery."
}
